import React, { useState, useEffect } from 'react'; // Import React and hooks for managing state and lifecycle
import axios from 'axios'; // Import axios for making HTTP requests
import './App.css'; // Import the stylesheet for the App component
import VehicleForm from './VehicleForm'; // Import the VehicleForm component
import StationForm from './StationForm'; // Import the StationForm component
import StepForm from './StepForm'; // Import the StepForm component
import MapComponent from './MapComponent'; // Import the MapComponent for rendering the map
import Papa from 'papaparse'; // Import Papa for parsing CSV files
import 'leaflet/dist/leaflet.css'; // Import Leaflet's CSS for map styling
import io from 'socket.io-client'; // Import socket.io-client for WebSocket communication
import { incrementId, incrementStepId, incrementStationId } from './global'; // Import helper functions for generating IDs

function App() {
  // State variables to manage visibility of forms and hold data
  const [showVehicleForm, setShowVehicleForm] = useState(false); // Toggle for displaying the Vehicle form
  const [showStationForm, setShowStationForm] = useState(false); // Toggle for displaying the Station form
  const [showStepForm, setShowStepForm] = useState(false); // Toggle for displaying the Step form
  const [vehicles, setVehicles] = useState([]); // State for holding the list of vehicles
  const [stations, setStations] = useState([]); // State for holding the list of stations
  const [steps, setSteps] = useState([]); // State for holding the list of steps
  const [newLocation, setNewLocation] = useState(null); // State for holding a new location selected on the map
  const [selectingLocation, setSelectingLocation] = useState(false); // State to check if a location is being selected
  const [selectedType, setSelectedType] = useState(null); // State for the type of object being placed (vehicle or station)
  const [selectedTrip, setSelectedTrip] = useState(0); // State for the selected trip calculation model
  const [selectedCharge, setSelectedCharge] = useState(0); // State for the selected charging model
  const [logs, setLogs] = useState([]); // State for holding logs from the simulation

  // useEffect hook to manage WebSocket connection and handle incoming data
  useEffect(() => {
    const socket = io('http://127.0.0.1:5000'); // Connect to the WebSocket server

    // Listen for 'log' events from the server and update the log and vehicle states
    socket.on('log', (data) => {
      console.log("Log received:", data);
      setLogs((prevLogs) => [...prevLogs, data.message]); // Append new log message to logs

      // Update vehicle data based on incoming data
      if (data.name) {
        const updatedVehicles = vehicles.map(vehicle => {
          if (vehicle.name === data.name) {
            // Update vehicle's location, battery, or both depending on the received data
            if (!data.battery) {
              vehicle.location = data.location;
            } else if (!data.location) {
              vehicle.battery = data.battery;
            } else {
              vehicle.battery = data.battery;
              vehicle.location = data.location;
            }
            console.log("Updating vehicle:", vehicle);
            console.log("vehicle is at ", vehicle.location.lat, vehicle.location.lng);
            return vehicle; // Return the updated vehicle
          }
          return vehicle; // Return unchanged vehicle
        });
        setVehicles(updatedVehicles); // Update the vehicles state with the modified data
      }
    });

    return () => {
      socket.disconnect(); // Clean up the socket connection when the component unmounts
    };
  }, [vehicles]);

  // Handle click events on the map to set the new location for a vehicle or station
  const handleMapClick = (location) => {
    if (location.lat === undefined || location.lng === undefined) {
      console.error('Invalid location object', location); // Error if location object is invalid
      return;
    }

    console.log('in handleMapClick', location.lat, location.lng);
    setNewLocation(location); // Update the state with the selected location

    if (selectingLocation && selectedType) {
      // Depending on the selected type (vehicle or station), update the corresponding location
      if (selectedType === 'vehicle') {
        console.log('in vehicle');
        updateVehicleLocation(location);

      } else if (selectedType === 'station') {
        console.log('in station');
        updateStationLocation(location);
      }
      setSelectingLocation(false); // Stop selecting location after setting it
    }
  };

  // Toggle the visibility of the Vehicle form
  const toggleVehicleForm = () => {
    setShowVehicleForm(!showVehicleForm);
  };

  // Function to add a new vehicle after form submission
  const addVehicle = (vehicleData) => {
    // Check if all required fields are filled
    if (!vehicleData.name || !vehicleData.battery_capacity || !vehicleData.consumption || !vehicleData.battery || !vehicleData.location || !vehicleData.start_time) {
      alert('Every field is required');
      return;
    }

    vehicleData.id = incrementId(); // Generate a new ID for the vehicle

    const newVehicle = {
      ...vehicleData,
    };

    // Send a POST request to the backend to add the new vehicle
    axios.post('http://127.0.0.1:5000/add_vehicle', newVehicle)
      .then(response => {
        setVehicles([...vehicles, vehicleData]); // Update the vehicles state with the new vehicle
        console.log(response.data.message); // Log the success message from the backend
        setShowVehicleForm(false); // Hide the form after submission
        setNewLocation(null); // Reset the new location state
      })
      .catch(error => {
        console.error('Error adding vehicle:', error); // Log any errors
        alert('Error adding vehicle: ' + error.message); // Show an error alert to the user
      });
  };

  // Toggle the visibility of the Station form
  const toggleStationForm = () => {
    setShowStationForm(!showStationForm);
  };

  // Function to add a new station after form submission
  const addStation = (stationData) => {
    // Check if all required fields are filled
    if (!stationData.name || !stationData.location || !stationData.charging_speed || !stationData.price_per_kwh || !stationData.buy_price_per_kwh || !stationData.discharging_speed) {
      alert('Every field is required');
      return;
    }
    stationData.id = incrementStationId(); // Generate a new ID for the station

    // Send a POST request to the backend to add the new station
    axios.post('http://127.0.0.1:5000/add_station', stationData)
      .then(response => {
        setStations([...stations, stationData]); // Update the stations state with the new station
        console.log(response.data.message); // Log the success message from the backend
        setShowStationForm(false); // Hide the form after submission
        setNewLocation(null); // Reset the new location state
      })
      .catch(error => {
        console.error('Error adding station:', error); // Log any errors
        alert('Error adding station: ' + error.message); // Show an error alert to the user
      });
  };

  // Toggle the visibility of the Step form
  const toggleStepForm = () => {
    setShowStepForm(!showStepForm);
  };

  // Function to add a new step after form submission
  const addStep = (stepData) => {
    if (!stepData.stepType){
      alert('choose a type'); // Ensure that the step type is selected
      return
    }
    stepData.id = incrementStepId(); // Generate a new ID for the step
    console.log(stepData);
    // Send a POST request to the backend to add the new step
    axios.post('http://127.0.0.1:5000/add_step', stepData)
      .then(response => {
        console.log('in then');
        setSteps([...steps, stepData]); // Update the steps state with the new step
        console.log(response.data.message); // Log the success message from the backend
        setShowStepForm(false); // Hide the form after submission
      })
      .catch(error => {
        console.error('Error adding step:', error); // Log any errors
      });
    };

  // Function to update the steps of a vehicle
  const updateVehicleSteps = (vehicleName, stepData) => {
    const updatedVehicles = vehicles.map(vehicle => {
      if (vehicle.name === vehicleName) {
        return { ...vehicle, steps: stepData }; // Update the steps of the matched vehicle
      }
      return vehicle;
    });
    setVehicles(updatedVehicles); // Update the vehicles state with the modified data
  };

  // Function to update the location of a vehicle
  const updateVehicleLocation = (vehicleName, newLocation) => {
    const updatedVehicles = vehicles.map(vehicle => {
      if (vehicle.name === vehicleName) {
        return { ...vehicle, location: newLocation }; // Update the location of the matched vehicle
      }
      return vehicle;
    });
    setVehicles(updatedVehicles); // Update the vehicles state with the modified data
  };

  // Function to update the location of a station
  const updateStationLocation = (stationName, newLocation) => {
    const updatedStations = stations.map(station => {
      if (station.name === stationName) {
        return { ...station, location: newLocation }; // Update the location of the matched station
      }
      return station;
    });
    setStations(updatedStations); // Update the stations state with the modified data
  };

  // Function to handle CSV file uploads for vehicles
  const handleVehicleFileUpload = (event) => {
    const file = event.target.files[0]; // Get the selected file

    Papa.parse(file, {
      header: true, // Parse the CSV with headers
      complete: function(results) {
        const parsedData = results.data;
        parsedData.forEach(vehicle => {
          vehicle.id = incrementId(); // Assign a new ID to each vehicle
        });
        setVehicles(parsedData); // Update the vehicles state with the parsed data
      },
      error: function(error) {
        console.error('Error parsing CSV:', error); // Log any errors
      }
    });
  };

  // Function to handle CSV file uploads for stations
  const handleStationFileUpload = (event) => {
    const file = event.target.files[0]; // Get the selected file

    Papa.parse(file, {
      header: true, // Parse the CSV with headers
      complete: function(results) {
        const parsedData = results.data;
        parsedData.forEach(station => {
          station.id = incrementStationId(); // Assign a new ID to each station
        });
        setStations(parsedData); // Update the stations state with the parsed data
      },
      error: function(error) {
        console.error('Error parsing CSV:', error); // Log any errors
      }
    });
  };

  // Function to handle CSV file uploads for steps
  const handleStepFileUpload = (event) => {
    const file = event.target.files[0]; // Get the selected file

    Papa.parse(file, {
      header: true, // Parse the CSV with headers
      complete: function(results) {
        const parsedData = results.data;
        parsedData.forEach(step => {
          step.id = incrementStepId(); // Assign a new ID to each step
        });
        setSteps(parsedData); // Update the steps state with the parsed data
      },
      error: function(error) {
        console.error('Error parsing CSV:', error); // Log any errors
      }
    });
  };

  // Render the App component
  return (
    <div className="App">
      {/* Buttons to toggle form visibility */}
      <button onClick={toggleVehicleForm}>Add Vehicle</button>
      <button onClick={toggleStationForm}>Add Station</button>
      <button onClick={toggleStepForm}>Add Step</button>

      {/* Render forms conditionally based on state */}
      {showVehicleForm && <VehicleForm addVehicle={addVehicle} />}
      {showStationForm && <StationForm addStation={addStation} />}
      {showStepForm && <StepForm addStep={addStep} />}

      {/* Input fields for uploading CSV files */}
      <input type="file" onChange={handleVehicleFileUpload} />
      <input type="file" onChange={handleStationFileUpload} />
      <input type="file" onChange={handleStepFileUpload} />

      {/* Render the map component with vehicle, station, and step data */}
      <MapComponent vehicles={vehicles} stations={stations} steps={steps} onMapClick={handleMapClick} />
    </div>
  );
}

export default App;
